import {gapActors} from './seed';
import {reviewedSyntheticGap,gapEnvelope} from './authoring';
import {prepareGapReport,readGapReport} from '../../../lib/server/gaps/reports';
import {claimGapReportJobs,runGapReportJob} from '../../../lib/server/gaps/report-jobs';
import {previewGapReportReview,commitGapReportReview} from '../../../lib/server/gaps/report-review';
export async function preparedGapReport(empty=false){const actors=await gapActors(),gap=empty?null:await reviewedSyntheticGap(actors.panel,actors.mcteer),input={...gapEnvelope(),kind:empty?'portfolio' as const:'detail' as const,gapIds:gap?[gap.id]:[],asOf:new Date().toISOString(),comparisonAt:null,audience:{team:'Synthetic Functions engineering',recipients:['Synthetic Engineer'],purpose:'Assess exact synthetic reviewed capability'}},receipt=await prepareGapReport(actors.panel,input),jobs=await claimGapReportJobs();const job=jobs.find(j=>j.id===receipt.resultId);if(job)await runGapReportJob(job);else{const deadline=Date.now()+30000;for(;;){const current=await readGapReport(actors.panel,receipt.recordId!);if(current.job?.state==='prepared')break;if(Date.now()>=deadline||['failed','cancelled'].includes(current.job?.state??''))throw Error('Owned report preparation unavailable');await new Promise(resolve=>setTimeout(resolve,500));}}return {actors,gap,input,receipt,report:await readGapReport(actors.panel,receipt.recordId!)};}
export async function approvedGapReport(empty=false){const fixture=await preparedGapReport(empty),{report,actors}=fixture,preview=await previewGapReportReview(actors.mcteer,report.id,{...gapEnvelope(report.version),action:'approve',revisionId:report.revision!.id,customerDisclosures:report.document!.customers.map(c=>c.id),audienceDigest:report.revision!.audienceDigest,rationale:'Independent exact synthetic report review',selfReview:false});await commitGapReportReview(actors.mcteer,report.id,{...gapEnvelope(report.version),previewId:preview.resultId,bindingDigest:preview.bindingDigest});return {...fixture,report:await readGapReport(actors.mcteer,report.id)};}
